import mujoco
model = mujoco.MjModel.from_xml_path('model_ref.xml')
print('nplugin:', model.nplugin)
for i in range(model.nplugin):
    p = model.plugin[i]
    print(f'plugin {i}:')
    for attr in dir(p):
        if not attr.startswith('_'):
            try:
                val = getattr(p, attr)
                if not callable(val):
                    print(f'  {attr} = {val}')
            except:
                pass
